const LT={ru:{t:'Избранные стихи',rm:'Убрать',hint:'Сохранено ♥ Избранное — в меню ⋯'},en:{t:'Favorite verses',rm:'Remove',hint:'Saved ♥ Favorites are in the ⋯ menu'},hy:{t:'Ընտրյալ համարներ',rm:'Հեռացնել',hint:'Պահվեց ♥ Ընտրյալները՝ ⋯ ընտրացանկում'},de:{t:'Lieblingsverse',rm:'Entfernen',hint:'Gespeichert ♥ Favoriten im ⋯-Menü'}};
